parameters.jsCode:
let type = $json.message.type === "human" ? "Human" : "AI";
let content = $json.message.content;

return {
  json: {
    formatted_line: `${type}: ${content}`
  }
};

// Combine all formatted lines into one string
let conversation = items
  .map(item => item.json.formatted_line)
  .filter(line => line && line.trim() !== '') // remove empty/null lines
  .map(line => line.replace(/\n+/g, ' '))     // replace multiple \n with a single space inside messages
  .join('\n');                                // one \n between messages

return [
  {
    json: {
      full_conversation: conversation
    }
  }
];

